//! 🧷️ Collection operations bind exact original array addresses without manufacturing semantic members.
use super::*;
fn segments<'a>(field:&Field,row:&'a str,member:&'a str,create:bool)->([&'a str;10],usize){let words=["value","$ifcInputs",row,"value","value","items","0","value",member,"value"];let count=if create{6}else if field.operation==Some(false){8}else if field.operation==Some(true){9}else{10};(words,count)}
fn spec(field:&Field,request:&StagedFormRequest)->Result<bool,ValueError>{if !field.selection||field.operation.is_none(){return Err(invalid());}Ok(super::super::type_input::typed_constructor(constructor(request,field.row)?).ok_or_else(invalid)?.1.is_empty())}
pub(super) fn capacity(field:&Field,request:&StagedFormRequest)->Result<usize,ValueError>{let create=spec(field,request)?;let mut row=[0;20];let row=decimal(field.row,&mut row);let mut member=[0;20];let member=decimal(field.member.unwrap_or(0),&mut member);let(words,count)=segments(field,row,member,create);let path=count*size_of::<String>()+words[..count].iter().map(|word|word.len()).sum::<usize>();Ok(path+if field.operation==Some(false){if !create&&field.kind==InputKind::Array{3*size_of::<(String,DslValue)>()+17}else{2*size_of::<(String,DslValue)>()+18}}else{0})}
pub(super) fn advance(field:&Field,request:&StagedFormRequest,output:&mut Option<StagedFormBindingEdit>,base:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let create=spec(field,request)?;let mut row=[0;20];let row=decimal(field.row,&mut row);let mut member=[0;20];let member=decimal(field.member.unwrap_or(0),&mut member);let(words,count)=segments(field,row,member,create);let capacity=capacity(field,request)?;let copy=base+2*capacity+2*size_of::<StagedFormBindingEdit>()+2*size_of::<DslValue>();let physical=OriginalConstructionDemand{items:1,copy_bytes:copy,capacity_bytes:capacity,release_bytes:0,depth:4};admit_original_construction(cx,output,physical,|_|{let path=words[..count].iter().map(|word|String::from(*word)).collect::<Vec<_>>();let mut retained=path.capacity()*size_of::<String>()+path.iter().map(String::capacity).sum::<usize>();let edit=if field.operation==Some(true){StagedFormEdit::Remove{path}}else{let value=vec![("kind".into(),DslValue::String(if create{"aggregate"}else if field.kind==InputKind::Array{"real"}else if field.kind==InputKind::List{"integer"}else{"reference"}.into())),("value".into(),if create{DslValue::Array(Vec::new())}else if field.kind==InputKind::Array{DslValue::Object(vec![("bits".into(),DslValue::String(String::new()))])}else{DslValue::String(String::new())})];retained+=value.capacity()*size_of::<(String,DslValue)>();for(key,value)in &value{retained+=key.capacity();match value{DslValue::String(value)=>retained+=value.capacity(),DslValue::Object(fields)=>{retained+=fields.capacity()*size_of::<(String,DslValue)>();for(key,value)in fields{retained+=key.capacity();if let DslValue::String(value)=value{retained+=value.capacity();}}},_=>{}}}StagedFormEdit::Append{path,value:DslValue::Object(value)}};Ok((StagedFormBindingEdit::Fixed{edit},RetainedCloneProgress{copied_items:1,copied_bytes:copy,retained_capacity_bytes:retained,..Default::default()}))})}
pub(super) fn text_path(row:&str,member:&str,real:bool)->Vec<String>{let words=["value","$ifcInputs",row,"value","value","items","0","value",member,"value","bits"];words[..if real{11}else{10}].iter().map(|word|String::from(*word)).collect()}
